        forward_full(PARAMS, CFG, np.array([_make_prompt(length, SEED + 7)]), cache=cache)
        print(f"  {name}: measured {cache.nbytes_used():>8,} bytes; formula "
              f"{kv_cache_bytes(CFG, length, 1, cache.k.itemsize):>8,} bytes")
